<?php
declare(strict_types=1);
final class AdminRepositoryModel
{
 public function listing(string $filter=''):array{$where="p.deleted_at IS NULL AND p.status IN ('approved','completed','published')";$params=[];if(in_array($filter,['eligible','published','incomplete'],true)){if($filter==='published')$where.=" AND p.status='published'";elseif($filter==='eligible')$where.=" AND p.status IN ('approved','completed') AND EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)";else $where.=" AND p.status IN ('approved','completed') AND NOT EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)";}$sql="SELECT p.id,p.code,p.title,p.summary,p.status,p.published_at,p.updated_at,pt.name type_name,c.name career_name,ap.name period_name,u.full_name tutor_name,(SELECT COUNT(*) FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL) file_count,(SELECT GROUP_CONCAT(DISTINCT UPPER(f.extension) ORDER BY f.extension SEPARATOR ', ') FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL) formats FROM projects p JOIN project_types pt ON pt.id=p.project_type_id JOIN careers c ON c.id=p.career_id JOIN academic_periods ap ON ap.id=p.academic_period_id LEFT JOIN users u ON u.id=p.tutor_id WHERE $where ORDER BY COALESCE(p.published_at,p.updated_at) DESC";$q=Database::connection()->prepare($sql);$q->execute($params);return $q->fetchAll();}
 public function summary():array{$d=Database::connection();return ['eligible'=>(int)$d->query("SELECT COUNT(*) FROM projects p WHERE p.deleted_at IS NULL AND p.status IN ('approved','completed') AND EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)")->fetchColumn(),'published'=>(int)$d->query("SELECT COUNT(*) FROM projects WHERE deleted_at IS NULL AND status='published'")->fetchColumn(),'incomplete'=>(int)$d->query("SELECT COUNT(*) FROM projects p WHERE p.deleted_at IS NULL AND p.status IN ('approved','completed') AND NOT EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)")->fetchColumn()];}
 public function setPublished(int $id,bool $publish,int $actor):void{if($id<1)throw new InvalidArgumentException('El proyecto no es válido.');Database::transaction(function(PDO $d)use($id,$publish,$actor):void{$q=$d->prepare('SELECT id,title,status,published_at FROM projects WHERE id=:id AND deleted_at IS NULL FOR UPDATE');$q->execute(['id'=>$id]);$before=$q->fetch();if(!$before)throw new InvalidArgumentException('El proyecto ya no está disponible.');if($publish){if(!in_array($before['status'],['approved','completed'],true))throw new InvalidArgumentException('Solo se pueden publicar proyectos aprobados o finalizados.');$files=$d->prepare('SELECT COUNT(*) FROM project_files WHERE project_id=:id AND deleted_at IS NULL');$files->execute(['id'=>$id]);if((int)$files->fetchColumn()<1)throw new InvalidArgumentException('Agrega al menos un documento final antes de publicar.');$d->prepare("UPDATE projects SET status='published',published_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['id'=>$id]);$after=['status'=>'published'];$action='project_published';}else{if($before['status']!=='published')throw new InvalidArgumentException('El proyecto no está publicado.');$d->prepare("UPDATE projects SET status='completed',published_at=NULL WHERE id=:id")->execute(['id'=>$id]);$after=['status'=>'completed'];$action='project_unpublished';}(new ProjectAuditService($d))->record($id,$actor,$action,'project',$id,$before,$after);});}
}
